import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: { include: ['tests/**/*.test.ts'], environment: 'node' },
});

import { describe, expect, it } from 'vitest';
import { parseEvent, serializeEvent, type WorkerEvent } from '../src/events.js';

describe('events', () => {
  it('round-trips a pre_tool_use event', () => {
    const e: WorkerEvent = {
      event: 'pre_tool_use',
      ts: 'T',
      tool: 'Bash',
      tool_input: { cmd: 'ls' },
    };
    expect(parseEvent(serializeEvent(e))).toEqual(e);
  });
  it('parses a session_start with cwd', () => {
    expect(parseEvent('{"event":"session_start","ts":"T","cwd":"/x"}')).toEqual(
      {
        event: 'session_start',
        ts: 'T',
        cwd: '/x',
      },
    );
  });
  it('returns null for malformed json or unknown event', () => {
    expect(parseEvent('not json')).toBeNull();
    expect(parseEvent('{"event":"nope","ts":"T"}')).toBeNull();
  });
});

import { describe, expect, it } from 'vitest';
import { canonicalToolName } from '../src/core/tool-name.js';

describe('canonicalToolName', () => {
  it('title-cases the first letter so pi lowercase matches the Bash/Read convention', () => {
    expect(canonicalToolName('bash')).toBe('Bash');
    expect(canonicalToolName('read')).toBe('Read');
  });

  it('leaves an already-capitalized name unchanged', () => {
    expect(canonicalToolName('Bash')).toBe('Bash');
    expect(canonicalToolName('WebFetch')).toBe('WebFetch');
  });

  it('coerces empty / non-string (malformed payload) to an empty string', () => {
    expect(canonicalToolName('')).toBe('');
    expect(canonicalToolName(undefined)).toBe('');
    expect(canonicalToolName(null)).toBe('');
    expect(canonicalToolName(42)).toBe('');
  });
});

import { describe, expect, it } from 'vitest';
import { run } from '../src/core/proc.js';

describe('run()', () => {
  it('resolves with code 0 and captured stdout on success', async () => {
    const result = await run('node', ['-e', 'process.stdout.write("hi")']);
    expect(result.code).toBe(0);
    expect(result.stdout).toBe('hi');
  });

  it('resolves with the actual exit code on non-zero exit', async () => {
    const result = await run('node', ['-e', 'process.exit(3)']);
    expect(result.code).toBe(3);
  });

  it('resolves with code 1 and non-empty stderr on spawn failure (ENOENT)', async () => {
    const result = await run('definitely-not-a-real-binary-xyz', []);
    expect(result.code).toBe(1);
    expect(result.stderr).toBeTruthy();
    expect(result.stderr).toMatch(/definitely-not-a-real-binary-xyz/);
  });
});

