import { describe, expect, it } from 'vitest';
import { shellQuote, shellQuoteAlways } from '../src/core/shell.js';

/**
 * Pins the BEHAVIORAL DIFFERENCE between the two shell-quoting functions.
 * shellQuote has a safe-token fast path (for human-readable reproduce lines).
 * shellQuoteAlways has NO fast path (for args baked into re-evaluated strings).
 *
 * If a future consolidation removes the behavioral distinction, these tests
 * will catch it.
 */

describe('shellQuote (fast-path version)', () => {
  it('passes safe tokens through unquoted', () => {
    expect(shellQuote('worker1')).toBe('worker1');
    expect(shellQuote('/tmp/path-to_thing.js')).toBe('/tmp/path-to_thing.js');
    expect(shellQuote('safe_TOKEN')).toBe('safe_TOKEN');
    expect(shellQuote('a:b=c@d-e')).toBe('a:b=c@d-e');
  });

  it('quotes tokens with spaces', () => {
    expect(shellQuote('has space')).toBe("'has space'");
  });

  it('quotes tokens with special characters', () => {
    expect(shellQuote('a;b')).toBe("'a;b'");
  });

  it('escapes embedded single quotes', () => {
    expect(shellQuote("it's")).toBe("'it'\\''s'");
  });

  it('returns empty string as two single quotes', () => {
    expect(shellQuote('')).toBe("''");
  });
});

describe('shellQuoteAlways (no-fast-path version)', () => {
  it('always wraps safe tokens in single quotes — proving NO fast path', () => {
    // These are the same tokens shellQuote passes through unquoted.
    // shellQuoteAlways must wrap them to prove the behavioral difference is intact.
    expect(shellQuoteAlways('safe')).toBe("'safe'");
    expect(shellQuoteAlways('worker1')).toBe("'worker1'");
    expect(shellQuoteAlways('a:b=c@d-e')).toBe("'a:b=c@d-e'");
  });

  it('quotes tokens with spaces', () => {
    expect(shellQuoteAlways('has space')).toBe("'has space'");
  });

  it('escapes embedded single quotes with the POSIX trick', () => {
    expect(shellQuoteAlways("a'b")).toBe("'a'\\''b'");
    expect(shellQuoteAlways("it's")).toBe("'it'\\''s'");
  });

  it('wraps empty string in single quotes', () => {
    expect(shellQuoteAlways('')).toBe("''");
  });
});

import { describe, expect, it } from 'vitest';
import {
  countAssistantTextMessages,
  lastAssistantText,
} from '../src/core/assistant-text.js';

const lines = (...ls: string[]): string => ls.join('\n');

describe('countAssistantTextMessages', () => {
  it('counts only assistant messages with an array content containing text', () => {
    const t = lines(
      '{"type":"assistant","message":{"content":[{"type":"text","text":"a"}]}}',
      '{"type":"assistant","message":{"content":[{"type":"tool_use","name":"Bash","input":{}}]}}',
      '{"type":"assistant","message":{"content":[{"type":"thinking","thinking":"x"},{"type":"text","text":"b"}]}}',
      '{"type":"user","message":{"content":"hi"}}',
    );
    expect(countAssistantTextMessages(t)).toBe(2);
  });

  it('returns 0 for an empty transcript', () => {
    expect(countAssistantTextMessages('')).toBe(0);
  });

  it('ignores assistant lines whose content is a string (not an array)', () => {
    const t =
      '{"type":"assistant","message":{"content":"plain string content"}}';
    expect(countAssistantTextMessages(t)).toBe(0);
  });

  it('skips garbage/partial JSONL lines', () => {
    const t = lines(
      'not json',
      '{"type":"assistant","message":{"content":[{"type":"text","text":"a"}]}}',
    );
    expect(countAssistantTextMessages(t)).toBe(1);
  });
});

describe('lastAssistantText', () => {
  it('returns the text of the LAST assistant message that has text', () => {
    const t = lines(
      '{"type":"assistant","message":{"content":[{"type":"text","text":"first"}]}}',
      '{"type":"assistant","message":{"content":[{"type":"tool_use","name":"Bash","input":{}}]}}',
      '{"type":"assistant","message":{"content":[{"type":"text","text":"second"}]}}',
    );
    expect(lastAssistantText(t)).toBe('second');
  });

  it('joins multiple text blocks in the last message with newlines', () => {
    const t =
      '{"type":"assistant","message":{"content":[{"type":"text","text":"line one"},{"type":"thinking","thinking":"x"},{"type":"text","text":"line two"}]}}';
    expect(lastAssistantText(t)).toBe('line one\nline two');
  });

  it('returns empty string when there is no assistant text message', () => {
    const t =
      '{"type":"assistant","message":{"content":[{"type":"tool_use","name":"Bash","input":{}}]}}';
    expect(lastAssistantText(t)).toBe('');
  });

  it('returns empty string for an empty transcript', () => {
    expect(lastAssistantText('')).toBe('');
  });
});

import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { CommandContext } from '../src/commands/context.js';
import { awaitPiReady } from '../src/commands/pi-launch.js';
import type { Tmux } from '../src/core/tmux.js';
import { getDriver } from '../src/harness/registry.js';

function tmpDir(): string {
  return mkdtempSync(join(tmpdir(), 'csd-pi-launch-'));
}

interface FakeTmuxCalls {
  capturePane: string[];
}

/** A fake tmux whose pane text is computed per-capture by `paneText`. */
function fakeTmux(calls: FakeTmuxCalls, paneText: () => string): Tmux {
  return {
    async hasSession() {
      return true;
    },
    async killSession() {},
    async capturePane(name: string) {
      calls.capturePane.push(name);
      return paneText();
    },
    async capturePaneFull() {
      return paneText();
    },
    async sendText() {},
    async sendEnter() {},
    async sendKey() {},
    async newSession() {},
    async respawnPane() {},
  };
}

function makeCtx(workerDir: string, tmux: Tmux): CommandContext {
  return { workerDir, home: workerDir, tmux, driver: getDriver('pi') };
}

const TMUX_NAME = 'pi-worker';

describe('awaitPiReady', () => {
  let workerDir: string;

  beforeEach(() => {
    workerDir = tmpDir();
  });

  afterEach(() => {
    rmSync(workerDir, { recursive: true });
  });

  it('returns once the pi status-bar gauge appears', async () => {
    const calls: FakeTmuxCalls = { capturePane: [] };
    // Big timeout so the test only finishes fast if the gauge is seen.
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => '0.0%/272k (auto)'),
    );
    await awaitPiReady(ctx, TMUX_NAME, { timeoutMs: 5000, pollMs: 10 });
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });

  it('returns once a leading composer prompt glyph appears', async () => {
    const calls: FakeTmuxCalls = { capturePane: [] };
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => '> '),
    );
    await awaitPiReady(ctx, TMUX_NAME, { timeoutMs: 5000, pollMs: 10 });
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });

  it('returns after the timeout when no indicator appears (best-effort)', async () => {
    const calls: FakeTmuxCalls = { capturePane: [] };
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'still booting, nothing useful here'),
    );
    // Must resolve (not throw, not hang) even though nothing matches.
    await awaitPiReady(ctx, TMUX_NAME, { timeoutMs: 50, pollMs: 10 });
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });
});

