import { existsSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { CommandContext } from '../src/commands/context.js';
import { cmdGrantConsent } from '../src/commands/grant-consent.js';
import { consentPath, grantConsent } from '../src/core/consent.js';
import { makeTmux } from '../src/core/tmux.js';
import { getDriver } from '../src/harness/registry.js';

function tmpHome(): string {
  return mkdtempSync(join(tmpdir(), 'csd-gc-home-'));
}

function makeCtx(home: string): CommandContext {
  return {
    workerDir: home,
    home,
    tmux: makeTmux(async () => ({ stdout: '', stderr: '', code: 0 })),
    driver: getDriver('claude'),
  };
}

describe('cmdGrantConsent', () => {
  let home: string;

  beforeEach(() => {
    home = tmpHome();
  });

  afterEach(() => {
    rmSync(home, { recursive: true });
  });

  it('reports already granted when consent file already exists', async () => {
    grantConsent(home);
    const result = await cmdGrantConsent(makeCtx(home), {
      confirm: async () => true,
    });
    expect(result.code).toBe(0);
    expect(result.stdout).toContain('already granted');
    expect(result.stdout).toContain(consentPath(home));
  });

  it('grants consent and reports success when confirm returns true', async () => {
    const result = await cmdGrantConsent(makeCtx(home), {
      confirm: async () => true,
    });
    expect(result.code).toBe(0);
    expect(result.stdout).toContain('Consent granted');
    expect(result.stdout).toContain(consentPath(home));
    expect(existsSync(consentPath(home))).toBe(true);
  });

  it('does not grant consent and returns code 1 when confirm returns false', async () => {
    const warned: string[] = [];
    const result = await cmdGrantConsent(makeCtx(home), {
      warn: (s) => warned.push(s),
      confirm: async () => false,
    });
    expect(result.code).toBe(1);
    expect(result.stderr).toContain('not granted');
    expect(warned.join('')).toContain('--dangerously-skip-permissions');
    expect(existsSync(consentPath(home))).toBe(false);
  });

  it('emits the full risk warning BEFORE prompting (bash prints, then reads)', async () => {
    const events: string[] = [];
    const result = await cmdGrantConsent(makeCtx(home), {
      warn: (s) => events.push(`warn:${s}`),
      confirm: async () => {
        events.push('confirm');
        return true;
      },
    });
    expect(result.code).toBe(0);
    // The warning must be emitted before confirm() prompts/reads.
    const warnIdx = events.findIndex((e) => e.startsWith('warn:'));
    const confirmIdx = events.indexOf('confirm');
    expect(warnIdx).toBeGreaterThanOrEqual(0);
    expect(confirmIdx).toBeGreaterThan(warnIdx);
    expect(events[warnIdx]).toContain('--dangerously-skip-permissions');
  });
});

import { existsSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { CommandContext } from '../src/commands/context.js';
import { cmdPrune } from '../src/commands/prune.js';
import { harnessMarkerPath, metaPath, shimPath } from '../src/core/paths.js';
import { makeTmux } from '../src/core/tmux.js';
import {
  writeHarnessMarker,
  writeMeta,
  writeShim,
} from '../src/core/worker-store.js';
import { getDriver } from '../src/harness/registry.js';

/** A session is alive iff its name is in `alive` (decided by the has-session -t arg). */
function makeCtx(dir: string, alive: Set<string>): CommandContext {
  const tmux = makeTmux(async (_cmd, args) => {
    if (args[0] === 'has-session') {
      const name = args[args.indexOf('-t') + 1] ?? '';
      return { stdout: '', stderr: '', code: alive.has(name) ? 0 : 1 };
    }
    return { stdout: '', stderr: '', code: 0 };
  });
  return { workerDir: dir, home: dir, tmux, driver: getDriver('claude') };
}

describe('cmdPrune', () => {
  let dir: string;
  beforeEach(() => {
    dir = mkdtempSync(join(tmpdir(), 'csd-prune-'));
  });
  afterEach(() => {
    rmSync(dir, { recursive: true });
  });

  const mk = (name: string, sid: string) =>
    writeMeta(dir, {
      tmux_name: name,
      session_id: sid,
      cwd: '/w',
      harness: 'claude',
    });

  it('removes gone workers, keeps live ones, and reports the count', async () => {
    mk('alive1', 'sid-a');
    mk('dead1', 'sid-d1');
    mk('dead2', 'sid-d2');

    const result = await cmdPrune(makeCtx(dir, new Set(['alive1'])));

    expect(result.code).toBe(0);
    // live worker untouched; gone workers' state removed
    expect(existsSync(metaPath(dir, 'sid-a'))).toBe(true);
    expect(existsSync(metaPath(dir, 'sid-d1'))).toBe(false);
    expect(existsSync(metaPath(dir, 'sid-d2'))).toBe(false);
    expect(result.stdout).toContain('2');
    expect(result.stdout).toContain('dead1');
    expect(result.stdout).toContain('dead2');
    expect(result.stdout).not.toContain('alive1');
  });

  it('reports nothing to prune when every worker is live', async () => {
    mk('alive1', 'sid-a');
    const result = await cmdPrune(makeCtx(dir, new Set(['alive1'])));
    expect(result.code).toBe(0);
    expect(result.stderr).toBe('Nothing to prune');
    expect(result.stdout).toBeUndefined();
  });

  it('sweeps meta-less orphan sidecars/shims whose tmux is gone, keeps live ones (N-3)', async () => {
    // Orphan: a .harness sidecar + shim with no meta, tmux session dead.
    writeHarnessMarker(dir, 'orphan', 'codex');
    writeShim(dir, 'orphan', '/dist/csd.cjs');
    // A live derive worker mid-registration: same shape, but tmux still alive.
    writeHarnessMarker(dir, 'pending', 'codex');
    writeShim(dir, 'pending', '/dist/csd.cjs');

    const result = await cmdPrune(makeCtx(dir, new Set(['pending'])));

    expect(result.code).toBe(0);
    expect(result.stdout).toContain('orphan');
    // orphan removed, pending (live) untouched.
    expect(existsSync(harnessMarkerPath(dir, 'orphan'))).toBe(false);
    expect(existsSync(shimPath(dir, 'orphan'))).toBe(false);
    expect(existsSync(harnessMarkerPath(dir, 'pending'))).toBe(true);
    expect(existsSync(shimPath(dir, 'pending'))).toBe(true);
  });
});

import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import {
  awaitComposerReady,
  dismissCodexTrustGate,
} from '../src/commands/codex-launch.js';
import type { CommandContext } from '../src/commands/context.js';
import type { Tmux } from '../src/core/tmux.js';
import { getDriver } from '../src/harness/registry.js';

function tmpDir(): string {
  return mkdtempSync(join(tmpdir(), 'csd-codex-launch-'));
}

interface FakeTmuxCalls {
  capturePane: string[];
  sendText: { name: string; text: string }[];
  sendEnter: string[];
}

/**
 * A fake tmux whose pane text is computed per-capture by `paneText` (so a test
 * can return the trust gate or the composer glyph on demand, or never match).
 */
function fakeTmux(calls: FakeTmuxCalls, paneText: () => string): Tmux {
  return {
    async hasSession() {
      return true;
    },
    async killSession() {},
    async capturePane(name: string) {
      calls.capturePane.push(name);
      return paneText();
    },
    async capturePaneFull() {
      return paneText();
    },
    async sendText(name: string, text: string) {
      calls.sendText.push({ name, text });
    },
    async sendEnter(name: string) {
      calls.sendEnter.push(name);
    },
    async sendKey() {},
    async newSession() {},
    async respawnPane() {},
  };
}

function freshCalls(): FakeTmuxCalls {
  return { capturePane: [], sendText: [], sendEnter: [] };
}

function makeCtx(workerDir: string, tmux: Tmux): CommandContext {
  return { workerDir, home: workerDir, tmux, driver: getDriver('codex') };
}

const TMUX_NAME = 'codex-worker';
// Tiny windows so the never-match cases settle fast.
const FAST = { timeoutMs: 60, pollMs: 10, settleMs: 0 };

describe('dismissCodexTrustGate', () => {
  let workerDir: string;

  beforeEach(() => {
    workerDir = tmpDir();
  });

  afterEach(() => {
    rmSync(workerDir, { recursive: true });
  });

  it('sends "2" then Enter when the trust gate text appears', async () => {
    const calls = freshCalls();
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'Hooks need review'),
    );
    await dismissCodexTrustGate(ctx, TMUX_NAME, FAST);
    expect(calls.sendText).toEqual([{ name: TMUX_NAME, text: '2' }]);
    expect(calls.sendEnter).toEqual([TMUX_NAME]);
  });

  it('matches the alternate "Trust all and continue" phrasing (case-insensitive)', async () => {
    const calls = freshCalls();
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'Press 2 to Trust all and continue'),
    );
    await dismissCodexTrustGate(ctx, TMUX_NAME, FAST);
    expect(calls.sendText).toEqual([{ name: TMUX_NAME, text: '2' }]);
    expect(calls.sendEnter).toEqual([TMUX_NAME]);
  });

  it('returns without sending anything when the gate never appears (best-effort)', async () => {
    const calls = freshCalls();
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'just a normal pane'),
    );
    await dismissCodexTrustGate(ctx, TMUX_NAME, FAST);
    expect(calls.sendText).toEqual([]);
    expect(calls.sendEnter).toEqual([]);
    // It polled at least once before giving up.
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });
});

describe('awaitComposerReady', () => {
  let workerDir: string;

  beforeEach(() => {
    workerDir = tmpDir();
  });

  afterEach(() => {
    rmSync(workerDir, { recursive: true });
  });

  it('returns once the composer glyph appears', async () => {
    const calls = freshCalls();
    // Big timeout so the test only finishes fast if the glyph is seen.
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'ready ›'),
    );
    await awaitComposerReady(ctx, TMUX_NAME, {
      timeoutMs: 5000,
      pollMs: 10,
    });
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });

  it('returns after the timeout when the glyph never appears (best-effort)', async () => {
    const calls = freshCalls();
    const ctx = makeCtx(
      workerDir,
      fakeTmux(calls, () => 'no glyph here'),
    );
    // Must resolve (not throw, not hang) even though the glyph never shows.
    await awaitComposerReady(ctx, TMUX_NAME, { timeoutMs: 50, pollMs: 10 });
    expect(calls.capturePane.length).toBeGreaterThan(0);
  });
});
